/* @autogenerated */
import { Component } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { BehaviorSubject } from 'rxjs';
import { TranslocoService, TRANSLOCO_CONFIG } from '@jsverse/transloco';
import { EditablePasswordComponent } from './editable-password.component';

class MockTranslocoService {
  config = { reRenderOnLangChange: false };
  langChanges$ = new BehaviorSubject('en');
  translate = jasmine.createSpy('translate').and.callFake((value: string) => value);
  setActiveLang = jasmine.createSpy('setActiveLang');
  getActiveLang = () => 'en';
  getTranslation = () => ({});
}

@Component({
  imports: [ReactiveFormsModule, EditablePasswordComponent],
  template: `<editable-password label="password" [formControl]="control" />`,
})
class HostComponent {
  control = new FormControl<string | null>(null);
}

describe('EditablePasswordComponent', () => {
  afterEach(() => TestBed.resetTestingModule());

  function setup(value: string | null, disabled = false) {
    TestBed.configureTestingModule({
      imports: [HostComponent],
      providers: [
        { provide: TranslocoService, useClass: MockTranslocoService },
        {
          provide: TRANSLOCO_CONFIG,
          useValue: {
            availableLangs: ['en'],
            defaultLang: 'en',
            reRenderOnLangChange: false,
            prodMode: true,
          },
        },
      ],
    });
    const fixture = TestBed.createComponent(HostComponent);
    fixture.componentInstance.control = new FormControl({ value, disabled });
    fixture.detectChanges();
    const element: HTMLElement = fixture.nativeElement;
    return {
      fixture,
      input: element.querySelector('input') as HTMLInputElement,
      button: element.querySelector('.mat-mdc-form-field-icon-suffix button') as HTMLButtonElement | null,
    };
  }

  it('offers "assign" with an empty field when there is no password', () => {
    const { fixture, input, button } = setup(null);
    const editable = fixture.debugElement.children[0].componentInstance as EditablePasswordComponent;

    expect(editable.hasValue()).toBeFalse();
    expect(button).not.toBeNull();
    expect(input.value).toBe('');
  });

  it('offers "change" with a fixed mask when there is a password', () => {
    const { fixture, input, button } = setup('secret123');
    const editable = fixture.debugElement.children[0].componentInstance as EditablePasswordComponent;

    expect(editable.hasValue()).toBeTrue();
    expect(button).not.toBeNull();
    expect(input.value).toBe('••••••••');
    expect(input.value).not.toContain('secret');
  });

  it('keeps the button in the suffix, on the same line as the input', () => {
    const { fixture } = setup(null);
    const element: HTMLElement = fixture.nativeElement;

    expect(element.querySelector('.mat-mdc-form-field-infix button')).toBeNull();
  });

  it('reflects disabled: input disabled and no action button', () => {
    const { fixture, input, button } = setup('secret123', true);

    expect(input.disabled).toBeTrue();
    expect(button).toBeNull();
    expect(fixture.nativeElement.querySelector('.mat-form-field-disabled')).not.toBeNull();
  });

  it('applies the dialog password to the control', () => {
    const { fixture } = setup(null);
    const editable = fixture.debugElement.children[0].componentInstance as EditablePasswordComponent;

    editable.passwordForm.setValue({ newPassword: 'abcdef', confirmPassword: 'abcdef' });
    editable.update();
    fixture.detectChanges();

    expect(fixture.componentInstance.control.value).toBe('abcdef');
    expect(fixture.componentInstance.control.dirty).toBeTrue();
  });

  it('rejects mismatched confirmation', () => {
    const { fixture } = setup(null);
    const editable = fixture.debugElement.children[0].componentInstance as EditablePasswordComponent;

    editable.passwordForm.setValue({ newPassword: 'abcdef', confirmPassword: 'abcdeg' });
    editable.update();

    expect(editable.passwordForm.hasError('passwordMismatch')).toBeTrue();
    expect(fixture.componentInstance.control.value).toBeNull();
  });
});
